# patchwork + cowplot multi-panel composites (typical Fig. 1 layout) from Zeisel 2015
suppressPackageStartupMessages({library(patchwork); library(cowplot); library(Seurat); library(ggplot2); library(dplyr)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
so <- readRDS("../_data/zeisel_seurat.rds"); so$tissue <- ifelse(so$tissue == "sscortex", "S1 cortex", "CA1")
a <- DimPlot(so, group.by = "celltype", label = TRUE, repel = TRUE, label.size = 3) + NoLegend() + ggtitle("cell types")
b <- DimPlot(so, group.by = "tissue", cols = c("#1b9e77","#d95f02")) + ggtitle("tissue")
c <- VlnPlot(so, c("Snap25","Mbp","Aqp4"), group.by = "celltype", pt.size = 0, stack = TRUE, flip = TRUE) + NoLegend() + theme(axis.title.x = element_blank())
d <- so@meta.data %>% count(tissue, celltype) %>% group_by(tissue) %>% mutate(f = n / sum(n)) %>% ggplot(aes(tissue, f, fill = celltype)) + geom_col() + theme_classic() + labs(y = "fraction", x = NULL)
e <- DotPlot(so, features = c("Gad1","Slc17a7","Neurod6","Mbp","Aqp4","Cx3cr1","Cldn5"), group.by = "celltype") + RotatedAxis() + theme(axis.title = element_blank())
p <- (a | b) / (c | d | e) + plot_layout(heights = c(1.1, 1), widths = c(1, 1, 1.5)) + plot_annotation(tag_levels = "A", title = "patchwork composite: Zeisel 2015 overview") & theme(plot.tag = element_text(face = "bold", size = 16))
ggsave("v1_patchwork_composite.png", p, width = 15, height = 10, dpi = 110, bg = "white")
lay <- c(area(1,1,2,2), area(1,3,1,3), area(2,3,2,3)); ggsave("v2_patchwork_design_inset.png", a + c + d + plot_layout(design = lay) + inset_element(b + NoLegend() + theme_void(), .02, .6, .35, .98, on_top = TRUE), width = 12, height = 7, dpi = 120, bg = "white")
top <- plot_grid(a, b, labels = c("a","b"), rel_widths = c(1, 1.15)); bot <- plot_grid(c, d, e, labels = c("c","d","e"), nrow = 1, rel_widths = c(1, .8, 1.4), align = "h", axis = "b")
cw <- ggdraw(plot_grid(top, bot, ncol = 1, rel_heights = c(1.1, 1))) + draw_label("DRAFT", angle = 45, size = 90, alpha = .08, colour = "grey30")
ggsave("v3_cowplot_grid_watermark.png", cw, width = 15, height = 10, dpi = 110, bg = "white")
